// порядок (Ваня, 13.11): русский — последним
const LANGS = [["uk", "UA"], ["en", "EN"], ["de", "DE"], ["es", "ES"], ["fr", "FR"], ["it", "IT"], ["pl", "PL"], ["pt", "PT"], ["tr", "TR"],
  ["zh", "ZH"], ["ja", "JA"], ["ko", "KO"], ["fi", "FI"], ["ru", "RU"]].filter(([c]) => I18N[c]);
const LANG_NAMES = { uk: "Українська", en: "English", de: "Deutsch", es: "Español", fr: "Français", it: "Italiano", pl: "Polski", pt: "Português (Brasil)",
  tr: "Türkçe", ru: "Русский", zh: "简体中文", ja: "日本語", ko: "한국어", fi: "Suomi" };
const HTML_LANG = { zh: "zh-Hans", pt: "pt-BR" };   // атрибут lang: по нему Edge берет шрифт для иероглифов (и :lang() в стилях)
const hl = c => HTML_LANG[c] || c;
// турецкий КАПС делает из i точечную İ — для своих слов это верно, для названий песен / профилей / брендов нет: им lang="en"
const dataLang = () => LANG === "tr" ? ' lang="en"' : "";
let LANG = (() => {
  try { const s = localStorage.getItem("lang"); if (s && I18N[s]) return s; } catch (e) {}
  return "en";   // до выбора — English, не язык Windows (Ваня 13.11: международный; у него Windows ru-UA давала русский)
})();

function t(k, p) {
  let s = (I18N[LANG] && I18N[LANG][k]) ?? I18N.en[k] ?? k;
  if (p) for (const [a, b] of Object.entries(p)) s = s.split("{" + a + "}").join(b);
  return s;
}

function applyI18n(titleKey) {
  document.documentElement.lang = hl(LANG);
  document.querySelectorAll("[data-i18n]").forEach(e => e.innerHTML = t(e.dataset.i18n));
  document.querySelectorAll("[data-i18n-ph]").forEach(e => e.placeholder = t(e.dataset.i18nPh));
  document.querySelectorAll("[data-i18n-title]").forEach(e => e.title = t(e.dataset.i18nTitle));
  if (titleKey) document.title = t(titleKey);
}

// переключатель языка: кнопка «UA ▾» → список (названия на своем языке), внизу серая строка «переводы сделаны ИИ»
function langSwitcher(el, onChange) {
  const cur = (LANGS.find(([c]) => c === LANG) || ["", LANG.toUpperCase()])[1];
  el.innerHTML = `<div class="lsel"><button type="button" class="lcur" aria-haspopup="listbox" title="${t("langT")}">${cur} ▾</button>` +
    `<div class="lmenu" role="listbox">` +
    LANGS.map(([c, l]) => `<div class="li${c === LANG ? " on" : ""}" data-l="${c}" lang="${hl(c)}" role="option"><b>${l}</b>${LANG_NAMES[c]}</div>`).join("") +
    `<div class="lnote">${t("aiNote")}</div></div></div>`;
  const box = el.querySelector(".lsel");
  const outside = e => { if (!box.contains(e.target)) close(); };
  const esc = e => { if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); close(); } };
  const close = () => { box.classList.remove("open"); document.removeEventListener("click", outside, true); document.removeEventListener("keydown", esc, true); };
  box.querySelector(".lcur").onclick = () => {
    if (box.classList.toggle("open")) { document.addEventListener("click", outside, true); document.addEventListener("keydown", esc, true); }
    else close();
  };
  box.querySelector(".lmenu").onclick = e => {
    const it = e.target.closest("[data-l]"); if (!it) return;
    const c = it.dataset.l; close(); if (c === LANG) return;
    LANG = c; try { localStorage.setItem("lang", c); } catch (err) {}
    langSwitcher(el, onChange); onChange && onChange();
  };
}
